// Hold src/services/spSign.ts to the Python reference.
//
//   node scripts/check-sp-signing.mjs [path/to/client-signing.json]
//
// Vectors come from siLNt helpers/_client_signing_fixtures.py, generated by
// calling the same private helpers the /tx/build endpoint calls. Regenerate
// them after any change to the derivation, the fee formula or the output
// ordering, on either side.
//
// tx_hex is NOT compared: coincurve's sign_schnorr uses random aux data, so the
// two implementations never produce identical signature bytes. What is compared
// is everything deterministic — both output scripts, the amounts, the unsigned
// serialisation and each input's BIP-341 sighash — plus the stronger check that
// this side's signature VERIFIES against the Python's sighash under the input's
// own key. A transaction that matches all of those is one the network and the
// receiver's scanner will both accept.

import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

// Relative to this file, i.e. thrilla/scripts/ -> the sibling siLNt checkout.
const FIXTURES = process.argv[2] || '../../siLNt/fixtures/client-signing.json';

let failed = 0;
function ok(name, cond, detail = '') {
  console.log((cond ? '  ok   ' : '  FAIL ') + name);
  if (!cond) {
    if (detail) console.log('         ' + detail);
    failed++;
  }
}

const { __testing, buildSignedTx, DUST_SATS } = await import(
  pathToFileURL(new URL('../src/services/spSign.ts', import.meta.url).pathname).href
);
const { schnorr } = await import('@noble/curves/secp256k1');
const { toHex, fromHex, computeAmounts, spScriptPubKey, inputSigningKey,
        labelledChangeAddress, taprootSighash, serializeUnsigned } = __testing;

const data = JSON.parse(readFileSync(new URL(FIXTURES, import.meta.url), 'utf8'));

for (const c of data.cases) {
  console.log('\n' + c.name);
  const e = c.expected;
  const keys = c.utxos.map((u) => inputSigningKey(c.spend_key, u));

  // 1. amounts
  let amounts;
  try {
    amounts = computeAmounts(c.utxos, c.amount, c.fee_rate);
  } catch (err) {
    ok('amounts', false, String(err));
    continue;
  }
  ok('fee', amounts.fee === e.fee, `js ${amounts.fee} py ${e.fee}`);
  ok('change', amounts.change === e.change, `js ${amounts.change} py ${e.change}`);
  ok('total input', amounts.totalInput === e.total_input);
  ok('vsize', amounts.vsize === e.vsize, `js ${amounts.vsize} py ${e.vsize}`);

  // 2. the recipient output — the one that decides whether the payee ever
  //    finds the money
  const isSp = c.recipient.startsWith('sp1') || c.recipient.startsWith('tsp1');
  if (isSp) {
    const spk = toHex(spScriptPubKey(c.recipient, keys, c.utxos));
    ok('recipient scriptPubKey', spk === e.recipient_spk, `js ${spk}\n         py ${e.recipient_spk}`);
  }

  // 3. the change output
  if (e.change_spk) {
    const hrp = c.network === 'mainnet' ? 'sp' : 'tsp';
    const { secp256k1 } = await import('@noble/curves/secp256k1');
    const spendPub = secp256k1.getPublicKey(fromHex(c.spend_key), true);
    const addr = labelledChangeAddress(c.scan_secret, spendPub, 0, hrp);
    const spk = toHex(spScriptPubKey(addr, keys, c.utxos));
    ok('change scriptPubKey', spk === e.change_spk, `js ${spk}\n         py ${e.change_spk}`);
  } else {
    ok('no change output expected', amounts.change === 0);
  }

  // 4. the whole signed transaction, via the real entry point
  let built;
  try {
    built = buildSignedTx({
      recipient: c.recipient,
      recipientScriptHex: isSp ? undefined : e.recipient_spk,
      amount: c.amount,
      feeRate: c.fee_rate,
      utxos: c.utxos,
      spendKey: c.spend_key,
      scanSecret: c.scan_secret,
      network: c.network,
    });
  } catch (err) {
    ok('buildSignedTx', false, String(err));
    continue;
  }
  ok('built fee matches', built.fee === e.fee);
  ok('output count', (e.change_spk ? 2 : 1) === e.output_values.length);

  // 5. input order and the per-input sighash — where a silent disagreement
  //    would produce a transaction the network simply rejects
  const order = c.utxos
    .map((_u, i) => i)
    .sort((a, b) =>
      c.utxos[a].txid === c.utxos[b].txid
        ? c.utxos[a].vout - c.utxos[b].vout
        : c.utxos[a].txid < c.utxos[b].txid ? -1 : 1);
  const jsOrder = order.map((i) => `${c.utxos[i].txid}:${c.utxos[i].vout}`);
  ok('BIP-69 input order', JSON.stringify(jsOrder) === JSON.stringify(e.input_order),
     `js ${jsOrder}\n         py ${e.input_order}`);

  const vin = order.map((i) => ({ txid: c.utxos[i].txid, vout: c.utxos[i].vout }));
  const inAmounts = order.map((i) => c.utxos[i].amount);
  const inScripts = order.map((i) => fromHex('5120' + c.utxos[i].pub_key));
  const outs = e.output_values.map((v, i) => ({
    value: v, script: fromHex(e.output_scripts[i]),
  }));

  const unsigned = toHex(serializeUnsigned(vin, outs));
  ok('unsigned serialisation', unsigned === e.unsigned_tx,
     `js ${unsigned}\n         py ${e.unsigned_tx}`);

  let allMatch = true;
  let allVerify = true;
  for (let i = 0; i < vin.length; i++) {
    const h = toHex(taprootSighash(vin, outs, i, inAmounts, inScripts));
    if (h !== e.sighashes[i]) {
      allMatch = false;
      ok(`sighash[${i}]`, false, `js ${h}\n         py ${e.sighashes[i]}`);
    }
    // The signature this side produces must verify against the sighash the
    // PYTHON computed, under the key that is actually on chain.
    const sig = schnorr.sign(fromHex(e.sighashes[i]), keys[order[i]]);
    if (!schnorr.verify(sig, fromHex(e.sighashes[i]), fromHex(c.utxos[order[i]].pub_key))) {
      allVerify = false;
    }
  }
  ok('every sighash matches', allMatch);
  ok('every signature verifies against the Python sighash', allVerify);
}

console.log();
if (failed) {
  console.log(`${failed} FAILED`);
  process.exit(1);
}
console.log('all checks passed — the client builds what the server builds');
